import sqlite3
import json
import os

from copy import deepcopy

from taf.rfrl.procedures.resources.python.logger import log_warning, log_input_and_output
from taf.rfrl.procedures.resources.python.testline.TestLine import TestLine
from taf.rfrl.procedures.resources.python.alarms.GnbAlarms import GnbAlarms
from taf.rfrl.procedures.resources.python.alarms.EnbAlarms import EnbAlarms
from taf.rfrl.procedures.resources.python.alarms.exceptions import IncorrectBtsType, FaultSignatureFieldEmpty, \
    FaultIdNotProvided, AlarmIdNotProvided, FaultIdNotDefinedInDatabase
from taf.rfrl.procedures.resources.python.sw_update.SW_update import SW_update


class AlarmsManager(object):
    """
    Responsible for watching alarms on gNB and eNB.
    """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self._gnb_alarms = None
        self._enb_alarms = None
        self._alarms_db = None
        self._sw_version_cache = None
        self._watched_alarms = []

    @property
    def alarms_db(self):
        if self._alarms_db is None:
            self._alarms_db = sqlite3.connect(f'{os.path.split(os.path.abspath(__file__))[0]}/db/alarms.db')
        return self._alarms_db

    @property
    def bts_type(self):
        return TestLine().get_type_of_setup()

    @property
    def setup_mode(self):
        return TestLine().get_bts_setup_mode()

    @property
    def gnb_alarms(self):
        if self._gnb_alarms is None:
            self._gnb_alarms = GnbAlarms()
        return self._gnb_alarms

    @property
    def enb_alarms(self):
        if self._enb_alarms is None:
            self._enb_alarms = EnbAlarms()
        return self._enb_alarms

    @property
    def _sw_version(self):
        if self._sw_version_cache is None:
            self._sw_version_cache = SW_update().get_sw_version(bts_type=self.bts_type).raw
        return self._sw_version_cache

    def start_alarms_watchdog(self, tl, gnb_bts_id=0, enb_bts_id=0, log_dir='/tmp', interval='2 sec',
                              allowed_alarms_gnb=None, allowed_alarms_enb=None, on_gnb=True, on_enb=True):
        """
        Starts watching alarms on BTS with default allowed alarms unless different allowed_alarms are set.
        :param tl: testline object from init file
        :type tl: taf.config.testline.testline.TestLine
        :param gnb_bts_id: id of bts that should be used from tl.gnbs list; defaults to 0
        :type gnb_bts_id: Union[int, str]
        :param enb_bts_id: id of bts that should be used from tl.enbs list; defaults to 0
        :type enb_bts_id: Union[int, str]
        :param log_dir: path to logs directory
        :type log_dir: str
        :param interval: time interval between requests to BTS for active alarms; defaults to 2 sec
        :type interval: Union[float, int, str]
        :param allowed_alarms_gnb: list of allowed alarms for gnb, defaults to None which means that
                                   default list of allowed alarms will be used
        :type allowed_alarms_gnb: list of Alarm objects from taf.ul.alarms_watchdog
        :param allowed_alarms_enb: list of allowed alarms for enb, defaults to None which means that
                                   default list of allowed alarms will be used
        :type allowed_alarms_enb: list of Alarm objects from taf.ul.alarms_watchdog
        :param on_gnb: boolean value that defines whether watchdog on gNB bts should be started
        :type on_gnb: bool
        :param on_enb: boolean value that defines whether watchdog on eNB bts should be started
        :type on_enb: bool
        """
        if self._is_gnb() and on_gnb:
            self._watched_alarms.append(self.gnb_alarms)
            self.gnb_alarms.start_alarms_watchdog(bts_config=tl.gnbs[int(gnb_bts_id)], log_dir=log_dir,
                                                  interval=interval, allowed_alarms=allowed_alarms_gnb)

        if self._is_enb() and on_enb:
            self._watched_alarms.append(self.enb_alarms)
            self.enb_alarms.start_alarms_watchdog(bts_config=tl.enbs[int(enb_bts_id)], log_dir=log_dir,
                                                  interval=interval, allowed_alarms=allowed_alarms_enb)

    def check_alarms_and_stop_watchdog(self, reset_allowed_alarms_gnb=True, reset_allowed_alarms_enb=True, on_gnb=True,
                                       on_enb=True):
        """
        Checks whether alarms watchdog detected any disallowed alarms on BTS and stops watching alarms
        afterwards. If reset_allowed_alarms_gnb or reset_allowed_alarms_enb is set to True then allowed alarms will
        be reset to default for each bts type.
        :param reset_allowed_alarms_gnb: defines whether allowed alarms on gNB bts should be reset to default
        :type reset_allowed_alarms_gnb: bool
        :param reset_allowed_alarms_enb: defines whether allowed alarms on eNB bts should be reset to default
        :type reset_allowed_alarms_enb: bool
        :param on_gnb: boolean value that defines whether watchdog on gNB bts should be checked and stopped
        :type on_gnb: bool
        :param on_enb: boolean value that defines whether watchdog on eNB bts should be checked and stopped
        :type on_enb: bool
        """
        try:
            if self._is_gnb() and on_gnb:
                self.gnb_alarms.check_alarms_and_stop_watchdog(reset_allowed_alarms=reset_allowed_alarms_gnb)
        finally:
            if self._is_enb() and on_enb:
                self.enb_alarms.check_alarms_and_stop_watchdog(reset_allowed_alarms=reset_allowed_alarms_enb)

    def is_alarm_active(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, severity=None,
                        fault_signature=None, bts_type='GNB', unit_path=None):
        """
        Checks whether alarm with given attributes is currently active.
        At least one of alarm's attributes should be provided.
        :param alarm_id: ID of alarm, e.g. 10
        :type alarm_id: str or None
        :param fault_id: ID of fault, e.g. 1800
        :type fault_id: str or None
        :param fault_name: name of fault, e.g. No Connection To Unit
        :type fault_name: str or None
        :param hw_path: hardware path for alarm, e.g.
               /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1
        :type hw_path: str or None
        :param severity: used during comparison with severity of active alarms; defaults to None (not used)
        :type severity: str or None
        :param fault_signature: used during comparison with fault signature of active alarms; comparison will take
                                into account only provided attributes of fault signature; defaults to None (not used)
        :type fault_signature: dict or None
        :param bts_type: type of bts, can be GNB or ENB
        :type bts_type: str
        :param unit_path: WebM 'Configuration alarming object' column in active alarms, in AdmiApi active_alarm 'configObjectName'
                          e.g: '[ABIP_ORAN_AWHQN_CB011158] MRBTS-50438/EQM-1/APEQM-1/RMOD-1'
        :type unit_path: str
        :return: True is alarm is active, false otherwise
        :rtype: bool
        :raises IncorrectBtsType: when bts_type was neither GNB nor ENB
        """
        self._verify_bts_type(bts_type=bts_type)

        if self._is_gnb() and bts_type == "GNB":
            return self.gnb_alarms.is_alarm_active(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                                   hw_path=hw_path, severity=severity, fault_signature=fault_signature, unit_path=unit_path)
        elif self._is_enb() and bts_type == "ENB":
            return self.enb_alarms.is_alarm_active(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                                   hw_path=hw_path, severity=severity, fault_signature=fault_signature, unit_path=unit_path)

    def get_active_alarms(self, bts_type='GNB'):
        """
        Gets active alarms on eNB or gNB depending on bts_type
        :param bts_type: type of bts, can be GNB or ENB
        :type bts_type: str
        :return: list of active alarms
        :rtype: list
        :raises IncorrectBtsType: when bts_type was neither GNB nor ENB
        """
        self._verify_bts_type(bts_type=bts_type)

        if self._is_gnb() and bts_type == "GNB":
            return self.gnb_alarms.get_active_alarms()
        elif self._is_enb() and bts_type == "ENB":
            return self.enb_alarms.get_active_alarms()

    def extend_default_allowed_alarms(self, alarms=None, bts_type='GNB'):
        """
        Adds given alarms to default allowed alarms.
        :param alarms: alarms fault IDs which will be added to default allowed alarms
        :type alarms: list(int)
        :param bts_type: type of bts, can be GNB or ENB
        :type bts_type: str
        """
        self._verify_bts_type(bts_type=bts_type)

        if self._is_gnb() and bts_type == "GNB":
            return self.gnb_alarms.extend_default_allowed_alarms(alarms=alarms)
        elif self._is_enb() and bts_type == "ENB":
            return self.enb_alarms.extend_default_allowed_alarms(alarms=alarms)

    def create_alarm(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, fault_signature=None,
                     bts_type='GNB'):
        """
        Creates object of Alarm class from taf.ul.alarms_watchdog
        :param alarm_id: ID of alarm, e.g. 10
        :type alarm_id: str or None
        :param fault_id: ID of fault, e.g. 1800
        :type fault_id: str or None
        :param fault_name: name of fault, e.g. No Connection To Unit
        :type fault_name: str or None
        :param hw_path: hardware path for alarm, e.g.
               /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1
        :type hw_path: str or None
        :param fault_signature: used during comparison with fault signature of active alarms; comparison will take
                                into account only provided attributes of fault signature; defaults to None (not used)
        :type fault_signature: dict or None
        :param bts_type: type of bts, can be GNB or ENB; defaults to GNB
        :type bts_type: str
        :return: alarm with given parameters
        :rtype: Alarm
        :raises IncorrectBtsType: when bts_type was neither GNB nor ENB
        """
        self._verify_bts_type(bts_type=bts_type)

        if self._is_gnb() and bts_type == "GNB":
            return self.gnb_alarms.create_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                                hw_path=hw_path, fault_signature=fault_signature)
        elif self._is_enb() and bts_type == "ENB":
            return self.enb_alarms.create_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                                hw_path=hw_path, fault_signature=fault_signature)

    def wait_for_active_alarm(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, fault_signature=None,
                              reason=None, timeout=90, bts_type='GNB', unit_path=None):
        """
        Waits for alarm with given attributes to become active on BTS of type specified via bts_type parameter
        :param alarm_id: ID of alarm, e.g. 10
        :type alarm_id: str or None
        :param fault_id: ID of fault, e.g. 1800
        :type fault_id: str or None
        :param fault_name: name of fault, e.g. No Connection To Unit
        :type fault_name: str or None
        :param hw_path: hardware path for alarm, e.g.
               /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1
        :type hw_path: str or None
        :param fault_signature: used during comparison with fault signature of active alarms; comparison will take
                                into account only provided attributes of fault signature; defaults to None (not used)
        :type fault_signature: dict or None
        :param reason: used during comparison with reason of active alarms,
               i.e. 'Failed sanity check point results: /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1:{1b, 2}';
               can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
               defaults to None (not used)
        :type reason: str, re.Pattern or None
        :param timeout: total time to wait for alarm to become active on BTS. Accepts Robot string time
               format i.e. 1 min 20 sec; defaults to 90 seconds.
        :type timeout: Union[str, int]
        :param bts_type: type of bts, can be GNB or ENB; defaults to GNB
        :type bts_type: str
        :param unit_path: WebM 'Configuration alarming object' in active alarms, in admiApi active_alarm 'configObjectName'
                          e.g: '[ABIP_ORAN_AWHQN_CB011158] MRBTS-50438/EQM-1/APEQM-1/RMOD-1'
        :type unit_path: str
        :return: True if alarm becomes active
        :rtype: Bool
        :raises IncorrectBtsType: when bts_type was neither GNB nor ENB
        :raises AlarmInactive: if alarm with provided attributes won't appear before timeout
        """
        self._verify_bts_type(bts_type=bts_type)

        if self._is_gnb() and bts_type == "GNB":
            return self.gnb_alarms.wait_for_active_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                                         hw_path=hw_path, reason=reason, timeout=timeout,
                                                         fault_signature=fault_signature, unit_path=unit_path)
        elif self._is_enb() and bts_type == "ENB":
            return self.enb_alarms.wait_for_active_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                                         hw_path=hw_path, reason=reason, timeout=timeout,
                                                         fault_signature=fault_signature, unit_path=unit_path)

    def wait_for_inactive_alarm(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, fault_signature=None,
                                timeout=90, bts_type='GNB', unit_path=None):
        """
        Waits for alarm with given attributes to become inactive on BTS of type specified via bts_type parameter
        :param alarm_id: ID of alarm, e.g. 10
        :type alarm_id: str or None
        :param fault_id: ID of fault, e.g. 1800
        :type fault_id: str or None
        :param fault_name: name of fault, e.g. No Connection To Unit
        :type fault_name: str or None
        :param hw_path: hardware path for alarm, e.g.
               /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1
        :type hw_path: str or None
        :param fault_signature: used during comparison with fault signature of active alarms; comparison will take
                                into account only provided attributes of fault signature; defaults to None (not used)
        :type fault_signature: dict or None
        :param timeout: total time to wait for alarm to become inactive on BTS. Accepts Robot string time
               format i.e. 1 min 20 sec; defaults to 90 seconds.
        :type timeout: Union[str, int]
        :param bts_type: type of bts, can be GNB or ENB; defaults to GNB
        :type bts_type: str
        :return: True if alarm becomes active
        :rtype: Bool
        :raises IncorrectBtsType: when bts_type was neither GNB nor ENB
        :raises AlarmActive: if alarm with provided attributes won't disappear before timeout
        """
        self._verify_bts_type(bts_type=bts_type)

        if self._is_gnb() and bts_type == "GNB":
            return self.gnb_alarms.wait_for_inactive_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name, hw_path=hw_path,
                                                           timeout=timeout, fault_signature=fault_signature, unit_path=unit_path)
        elif self._is_enb() and bts_type == "ENB":
            return self.enb_alarms.wait_for_inactive_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name, hw_path=hw_path,
                                                           timeout=timeout, fault_signature=fault_signature, unit_path=unit_path)

    def allow_alarm(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, unit_path=None, severity=None,
                    fault_signature=None, bts_type='GNB'):
        """
        Adds new alarm into list of alarms which will be skipped during active alarms check on BTS
        of type specified by bts_type parameter. At least fault_id should be provided.
        :param alarm_id: ID of alarm, e.g. 10
        :type alarm_id: str or None
        :param fault_id: ID of fault, e.g. 1800
        :type fault_id: str or None
        :param fault_name: name of fault, e.g. No Connection To Unit
        :type fault_name: str or None
        :param hw_path: hardware path for alarm, e.g.
               /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1
        :type hw_path: str or None
        :param unit_path: used during comparison with unit path of active alarms; defaults to None (not used)
        :type unit_path: str or None
        :param severity: used during comparison with severity of active alarms; defaults to None (not used)
        :type severity: str or None
        :param fault_signature: used during comparison with fault signature of active alarms; comparison will take
                                into account only provided attributes of fault signature; defaults to None (not used)
        :type fault_signature: dict or None
        :param bts_type: type of bts, can be GNB or ENB; defaults to GNB
        :type bts_type: str
        :raises IncorrectBtsType: when bts_type was neither GNB nor ENB
        :raises FaultIdNotProvided: when fault_id was not provided
        :raises AlarmIdNotProvided: when severity was provided but alarm_id was not
        """
        self._allow_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name, hw_path=hw_path,
                          unit_path=unit_path, severity=severity, fault_signature=fault_signature, bts_type=bts_type)

    def was_alarm_detected(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, severity=None,
                           reason=None, unit_path=None, impacted_cells_count=None, fault_signature=None,
                           bts_type='GNB'):
        """
        Checks whether watch history contains detected disallowed alarm with given attributes.
        Before using this method alarms watchdog needs to be started - watch_alarms method must be used first.
        :param alarm_id: used during comparison with alarm ID of detected alarms; defaults to None (not used)
        :type alarm_id: str or None
        :param fault_id: used during comparison with fault ID of detected alarms; defaults to None (not used)
        :type fault_id: str or None
        :param fault_name: used during comparison with fault name of detected alarms; defaults to None (not used)
        :type fault_name: str or None
        :param hw_path: used during comparison with HW path of detected alarms;
                        can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                        defaults to None (not used)
        :type hw_path: str, re.Pattern or None
        :param severity: used during comparison with severity of active alarms; defaults to None (not used)
        :type severity: str or None
        :param reason: used during comparison with reason of active alarms,
                       i.e. 'Failed sanity check point results: /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1:{1b, 2}';
                       can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                       defaults to None (not used)
        :type reason: str, re.Pattern or None
        :param unit_path: used during comparison with unit path of active alarms; defaults to None (not used)
        :type unit_path: str, re.Pattern or None
        :param impacted_cells_count: used during comparison with impacted cells count of active alarms;
                                     can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                     defaults to None (not used)
        :type impacted_cells_count: str or None
        :param fault_signature: used during comparison with fault signature of active alarms;
                                i.e. {'category': 'POWER_OFF',
                                      'component': '1M203838370',
                                      'date': '20230519090516.000+0300'}
                                comparison will take into account only provided attributes of fault signature;
                                can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                defaults to None (not used)
        :type fault_signature: dict or None
        :param bts_type: type of bts, can be GNB or ENB; defaults to GNB
        :type bts_type: str
        :return: if provided Alarm was detected during alarms watch then True will be returned, False otherwise.
        :rtype: bool
        :raises WatchdogNotStarted: when performing this action was not preceded with starting alarms watch
        :raises InvalidAlarm: when all of provided alarm's parameters will be None
        """
        self._verify_bts_type(bts_type=bts_type)

        if self._is_gnb() and bts_type == "GNB":
            return self.gnb_alarms.was_alarm_detected(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                                      hw_path=hw_path, severity=severity, reason=reason,
                                                      unit_path=unit_path, impacted_cells_count=impacted_cells_count,
                                                      fault_signature=fault_signature)
        elif self._is_enb() and bts_type == "ENB":
            return self.enb_alarms.was_alarm_detected(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                                      hw_path=hw_path, severity=severity, reason=reason,
                                                      unit_path=unit_path, impacted_cells_count=impacted_cells_count,
                                                      fault_signature=fault_signature)

    def _allow_alarm(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, unit_path=None, severity=None,
                     fault_signature=None, bts_type='GNB'):

        self._verify_bts_type(bts_type=bts_type)
        if not fault_id:
            raise FaultIdNotProvided("Fault ID was not provided")
        if severity and not alarm_id:
            raise AlarmIdNotProvided("When severity is provided, alarm ID must be provided as well")

        if (("SBTS25R1_ENB_0000_000000_000000" > self._sw_version >= "SBTS24R3_ENB_0000_000242_000000"
                or self._sw_version >= "SBTS25R1_ENB_0000_240926_000004")
                and not self._is_tmo_branch_with_unhidden_alarms()):
            self._allow_alarm_cni_127210(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name, hw_path=hw_path,
                                         unit_path=unit_path, severity=severity, fault_signature=fault_signature,
                                         bts_type=bts_type)
        else:
            self._allow_alarm_legacy(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name, hw_path=hw_path,
                                     unit_path=unit_path, severity=severity, fault_signature=fault_signature,
                                     bts_type=bts_type)

    def disallow_alarm(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, unit_path=None, severity=None,
                       fault_signature=None, bts_type='GNB'):
        """
        Removes alarm from list of alarms which will be skipped during active alarms check on BTS
        of type specified by bts_type parameter. At least fault_id should be provided.
        :param alarm_id: ID of alarm, e.g. 10
        :type alarm_id: str or None
        :param fault_id: ID of fault, e.g. 1800
        :type fault_id: str or None
        :param fault_name: name of fault, e.g. No Connection To Unit
        :type fault_name: str or None
        :param hw_path: hardware path for alarm, e.g.
               /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1
        :type hw_path: str or None
        :param unit_path: used during comparison with unit path of active alarms; defaults to None (not used)
        :type unit_path: str or None
        :param severity: used during comparison with severity of active alarms; defaults to None (not used)
        :type severity: str or None
        :param fault_signature: used during comparison with fault signature of active alarms; comparison will take
                                into account only provided attributes of fault signature; defaults to None (not used)
        :type fault_signature: dict or None
        :param bts_type: type of bts, can be GNB or ENB; defaults to GNB
        :type bts_type: str
        :raises IncorrectBtsType: when bts_type was neither GNB nor ENB
        :raises FaultIdNotProvided: when fault_id was not provided
        :raises AlarmIdNotProvided: when severity was provided but alarm_id was not
        """

        self._disallow_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name, hw_path=hw_path,
                             unit_path=unit_path, severity=severity, fault_signature=fault_signature, bts_type=bts_type)

    def _disallow_alarm(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, unit_path=None,
                        severity=None, fault_signature=None, bts_type='GNB'):

        self._verify_bts_type(bts_type=bts_type)
        if not fault_id:
            raise FaultIdNotProvided("Fault ID was not provided")
        if severity and not alarm_id:
            raise AlarmIdNotProvided("When severity is provided, alarm ID must be provided as well")

        if (("SBTS25R1_ENB_0000_000000_000000" > self._sw_version >= "SBTS24R3_ENB_0000_000242_000000"
                or self._sw_version >= "SBTS25R1_ENB_9999_240926_000004")
                and not self._is_tmo_branch_with_unhidden_alarms()):
            self._disallow_alarm_cni_127210(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                            hw_path=hw_path, unit_path=unit_path, severity=severity,
                                            fault_signature=fault_signature, bts_type=bts_type)
        else:
            self._disallow_alarm_legacy(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name, hw_path=hw_path,
                                        unit_path=unit_path, severity=severity, fault_signature=fault_signature,
                                        bts_type=bts_type)

    def has_detected_alarms(self, bts_type='GNB'):
        """
        Checks whether watch history contains any detected disallowed alarm on BTS
        of type specified by bts_type parameter.
        :param bts_type: type of bts, can be GNB or ENB; defaults to GNB
        :type bts_type: str
        :return: True if watch history contains any detected disallowed alarm, False otherwise.
        :rtype: bool
        :raises IncorrectBtsType: when bts_type was neither GNB nor ENB
        """
        self._verify_bts_type(bts_type=bts_type)

        if self._is_gnb() and bts_type == "GNB":
            return self.gnb_alarms.has_detected_alarms()
        elif self._is_enb() and bts_type == "ENB":
            return self.enb_alarms.has_detected_alarms()

    def check_detected_alarms(self, bts_type='GNB'):
        """
        Checks whether watch history contains any detected disallowed alarm on BTS
        of type specified by bts_type parameter.
        :param bts_type: type of bts, can be GNB or ENB; defaults to GNB
        :type bts_type: str
        :raises IncorrectBtsType: when bts_type was neither GNB nor ENB
        :raises DisallowedAlarmsDetected: when watch history contains at least one detected disallowed alarm
        """
        self._verify_bts_type(bts_type=bts_type)

        if self._is_gnb() and bts_type == "GNB":
            self.gnb_alarms.check_detected_alarms()
        elif self._is_enb() and bts_type == "ENB":
            self.enb_alarms.check_detected_alarms()

    def run_when_alarm_detected(self, trigger_alarms, callback, bts_type='GNB', *args, **kwargs):
        """
        Registers callback to be called when any of trigger alarms is detected and disallowed on BTS
        of type specified by bts_type parameter.
        :param trigger_alarms: list of alarms which, when disallowed and detected, will trigger callback execution;
                               when empty list or None is provided then any detected alarm will trigger callback;
        :type trigger_alarms: list(Alarm) or None
        :param callback: callable object (in most cases a function); it will NOT accept Robot keyword
        :type callback: Callable
        :param bts_type: type of bts, can be GNB or ENB; defaults to GNB
        :type bts_type: str
        :param args: positional arguments which will be passed to callback
        :param kwargs: keyword arguments which will be passed to callback
        :raises IncorrectBtsType: when bts_type was neither GNB nor ENB
        """
        self._verify_bts_type(bts_type=bts_type)

        if self._is_gnb() and bts_type == "GNB":
            self.gnb_alarms.run_when_alarm_detected(trigger_alarms, callback, *args, **kwargs)
        elif self._is_enb() and bts_type == "ENB":
            self.enb_alarms.run_when_alarm_detected(trigger_alarms, callback, *args, **kwargs)

    def stop_watching_alarms(self, bts_type='GNB'):
        """
        Stops watching active alarms for disallowed alarms on BTS of type specified by bts_type parameter.
        :param bts_type: type of bts, can be GNB or ENB; defaults to GNB
        :type bts_type: str
        :raises IncorrectBtsType: when bts_type was neither GNB nor ENB
        """
        self._verify_bts_type(bts_type=bts_type)

        if self._is_gnb() and bts_type == "GNB":
            self.gnb_alarms.stop_watching_alarms()
        elif self._is_enb() and bts_type == "ENB":
            self.enb_alarms.stop_watching_alarms()

    def get_detected_alarms(self, bts_type='GNB'):
        """
        Returns list of alarms which were detected during active alarms check on BTS of type
        specified by bts_type parameter.
        :param bts_type: type of bts, can be GNB or ENB; defaults to GNB
        :type bts_type: str
        :return: list of currently detected alarms
        :rtype: list(Alarms)
        :raises IncorrectBtsType: when bts_type was neither GNB nor ENB
        """
        self._verify_bts_type(bts_type=bts_type)

        if self._is_gnb() and bts_type == "GNB":
            return self.gnb_alarms.get_detected_alarms()
        elif self._is_enb() and bts_type == "ENB":
            return self.enb_alarms.get_detected_alarms()

