    @staticmethod
    def create_dictionary_with_fault_signature_fields(**fields):
        """
        Creates dictionary with given fields and their values to be used in alarm's fault signature verification.
        If value of field is None then field with value will not be included in the dictionary.
        If no fields were given then None will be returned.
        :param fields: arguments representing alarm's fault signature fields and their expected values which
                       should be used during alarm check;
                       i.e. 'category'='SW_FAILURE', 'loadName'='SBTS25R1_ENB_9999_240926_000004', 'component'='1M203838370', 'scope'=None
        :type fields: kwargs (**dict)
        :return: dict of fields and their values, i.e. {'category': 'SW_FAILURE', 'loadName': 'SBTS25R1_ENB_9999_240926_000004',
                                                        'component'='1M203838370'}
        :rtype: dict or None
        """
        return {field: value for field, value in fields.items() if value is not None} if fields else None

    @staticmethod
    def verify_specific_fields_in_fault_signature_not_empty(alarm, *fields):
        """
        Verifies whether fields that were given are not empty in alarm's fault_signature
        :param alarm: taf.ul.alarms_watchdog.alarm.Alarm object to be verified
        :type alarm: taf.ul.alarms_watchdog.alarm.Alarm
        :param fields: names of fields that will be verified in fault_signature, i.e. date, resetCounter
        :type fields: tuple(str)
        :raises FaultSignatureFieldEmpty: when checked field in fault_signature contains no information
        """
        for field in fields:
            if alarm.fault_signature[str(field)] in ['-', '']:
                raise FaultSignatureFieldEmpty("Field {} in fault_signature for alarm: {} contains no information".
                                               format(field, alarm))

    def _is_enb(self):
        return self.setup_mode == "NSA" or self.bts_type == "ENB"

    def _is_gnb(self):
        return self.bts_type == "GNB"

    @staticmethod
    def _verify_bts_type(bts_type):
        if bts_type not in ["GNB", "ENB"]:
            raise IncorrectBtsType("Incorrect BTS type: {}. BTS type can be ENB or GNB.".format(bts_type))

    @log_input_and_output
    def _get_all_alarms_and_severity_for_fault_id(self, fault_id):
        """
        Gets visible alarm IDs for given fault ID from alarms database.
        :param fault_id: ID of fault, e.g. 1800
        :type fault_id: str
        :return: dict of all alarm IDs with severity levels
        :rtype: dict
        """
        alarm_ids = self._get_alarm_ids_with_severity_from_db_for_fault_id(table_name='alarms', fault_id=fault_id)
        if alarm_ids is None:
            raise FaultIdNotDefinedInDatabase(f"Fault ID {fault_id} is was not found in alarm database. "
                                              f"Please check if fault exists in NIDD!")
        return alarm_ids

    @log_input_and_output
    def _get_hidden_alarms_and_severity_for_fault_id(self, fault_id):
        """
        Gets visible alarm IDs for given fault ID from alarms database.
        :param fault_id: ID of fault, e.g. 1800
        :type fault_id: str
        :return: dict of hidden alarm IDs with severity levels
        :rtype: dict
        """
        alarm_ids = self._get_alarm_ids_with_severity_from_db_for_fault_id(table_name='hidden_alarms', fault_id=fault_id)
        if alarm_ids is None:
            return {}
        return alarm_ids

    def _get_alarm_ids_with_severity_from_db_for_fault_id(self, table_name, fault_id):
        cursor = self.alarms_db.cursor()
        cursor.execute(f'SELECT alarm_ids FROM {table_name} WHERE fault_id = ?', (fault_id,))
        fault_info = cursor.fetchone()
        if fault_info is None:
            return fault_info
        return json.loads(fault_info[0])

    @staticmethod
    @log_input_and_output
    def _get_visible_alarms_and_severity_for_fault_id(all_alarm_ids, hidden_alarm_ids):
        """
        Gets visible alarm IDs from given dicts of all and hidden alarms.
        :param all_alarm_ids: dict of all alarm IDs of particular fault ID
        :type all_alarm_ids: dict
        :param hidden_alarm_ids: dict of hidden alarm IDs of particular fault ID
        :type hidden_alarm_ids: dict
        :return: dict of visible alarm IDs
        :rtype: dict
        """
        visible_alarm_ids = deepcopy(all_alarm_ids)

        for hidden_alarm_id in hidden_alarm_ids.keys():
            if hidden_alarm_id in all_alarm_ids.keys():

                for hidden_severity in hidden_alarm_ids[hidden_alarm_id]:
                    if hidden_severity in all_alarm_ids[hidden_alarm_id]:
                        visible_alarm_ids[hidden_alarm_id].remove(hidden_severity)

        return visible_alarm_ids

    def _allow_alarm_legacy(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, unit_path=None,
                            severity=None, fault_signature=None, bts_type='GNB'):

        if self._is_gnb() and bts_type == "GNB":
            self.gnb_alarms.allow_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name, hw_path=hw_path,
                                        unit_path=unit_path, severity=severity, fault_signature=fault_signature)
        elif self._is_enb() and bts_type == "ENB":
            self.enb_alarms.allow_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name, hw_path=hw_path,
                                        unit_path=unit_path, severity=severity, fault_signature=fault_signature)

    def _allow_alarm_cni_127210(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, unit_path=None,
                                severity=None, fault_signature=None, bts_type='GNB'):

        alarms_instance = None
        all_alarm_ids = self._get_all_alarms_and_severity_for_fault_id(fault_id=fault_id)
        hidden_alarm_ids = self._get_hidden_alarms_and_severity_for_fault_id(fault_id=fault_id)
        visible_alarm_ids = self._get_visible_alarms_and_severity_for_fault_id(all_alarm_ids=all_alarm_ids,
                                                                               hidden_alarm_ids=hidden_alarm_ids)

        if self._is_gnb() and bts_type == "GNB":
            alarms_instance = self.gnb_alarms

        elif self._is_enb() and bts_type == "ENB":
            alarms_instance = self.enb_alarms

        if alarms_instance:
            if alarm_id:
                self._allow_alarm_with_alarm_id_and_severity(
                    alarm_instance=alarms_instance, alarm_id=alarm_id,
                    fault_id=fault_id, fault_name=fault_name,
                    hw_path=hw_path, unit_path=unit_path, severity=severity,
                    fault_signature=fault_signature, all_alarm_ids=all_alarm_ids,
                    visible_alarm_ids=visible_alarm_ids, hidden_alarm_ids=hidden_alarm_ids
                )
            elif visible_alarm_ids:
                self._allow_alarm_without_alarm_id_provided(alarm_instance=alarms_instance,
                                                            fault_id=fault_id, fault_name=fault_name,
                                                            hw_path=hw_path, unit_path=unit_path,
                                                            fault_signature=fault_signature,
                                                            visible_alarm_ids=visible_alarm_ids)
            else:
                alarms_instance.allow_alarm(fault_id=fault_id, fault_name=fault_name, hw_path=hw_path,
                                            unit_path=unit_path, fault_signature=fault_signature)

    @staticmethod
    def _verify_alarm_id_and_get_severity_levels(alarm_id, fault_id, visible_alarm_ids):
        visible_alarm_severity_levels = None
        try:
            visible_alarm_severity_levels = visible_alarm_ids[alarm_id]
        except KeyError:
            log_warning(f"Alarm ID '{alarm_id}' is not defined in alarms database for fault ID '{fault_id}' "
                        f"(check NIDD)")

        return visible_alarm_severity_levels

    @staticmethod
    def _verify_severity(alarm_id, fault_id, severity, all_alarm_ids, hidden_alarm_ids,):
        try:
            if severity in hidden_alarm_ids[alarm_id]:
                log_warning(f"Severity '{severity}' should not be allowed for fault ID '{fault_id}' "
                            f"with alarm ID '{alarm_id}' (check CNI-127210). Alarm will be added "
                            f"to allowed watchdog alarms.")
        except KeyError:
            pass
        try:
            if severity not in all_alarm_ids[alarm_id]:
                log_warning(f"Severity '{severity}' is not defined for fault ID '{fault_id}' with "
                            f"alarm ID '{alarm_id}' (check NIDD). Defined severity levels are "
                            f"'{all_alarm_ids[alarm_id]}'. Alarm will be added to allowed watchdog alarms.")
        except KeyError:
            pass

    @log_input_and_output
    def _allow_alarm_with_alarm_id_and_severity(self, alarm_instance, alarm_id, fault_id, fault_name, hw_path,
                                                unit_path, severity, fault_signature, all_alarm_ids,
                                                visible_alarm_ids, hidden_alarm_ids):

        visible_alarm_severity_levels = self._verify_alarm_id_and_get_severity_levels(
            fault_id=fault_id,
            alarm_id=alarm_id,
            visible_alarm_ids=visible_alarm_ids
        )

        if severity:
            self._verify_severity(fault_id=fault_id,
                                  alarm_id=alarm_id,
                                  severity=severity,
                                  all_alarm_ids=all_alarm_ids,
                                  hidden_alarm_ids=hidden_alarm_ids)
            alarm_instance.allow_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                       hw_path=hw_path, unit_path=unit_path, severity=severity,
                                       fault_signature=fault_signature)
        elif visible_alarm_severity_levels is not None:
            if not visible_alarm_severity_levels:
                log_warning(f"There are no visible severity levels for fault ID '{fault_id}' with "
                            f"alarm ID '{alarm_id}' (check CNI-127210). "
                            f"Alarm wont be added to allowed watchdog alarms.")
            for allowed_severity in visible_alarm_severity_levels:
                alarm_instance.allow_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                           hw_path=hw_path, unit_path=unit_path, severity=allowed_severity,
                                           fault_signature=fault_signature)

    @staticmethod
    @log_input_and_output
    def _allow_alarm_without_alarm_id_provided(alarm_instance, fault_id, fault_name, hw_path, unit_path,
                                               fault_signature, visible_alarm_ids):
        if any(visible_alarm_ids.values()):
            for visible_alarm_id in visible_alarm_ids:
                for allowed_severity in visible_alarm_ids[visible_alarm_id]:
                    alarm_instance.allow_alarm(alarm_id=visible_alarm_id, fault_id=fault_id, fault_name=fault_name,
                                               hw_path=hw_path, unit_path=unit_path, severity=allowed_severity,
                                               fault_signature=fault_signature)
        else:
            log_warning(f"No visible alarms detected for fault ID '{fault_id}' (check CNI-127210). "
                        f"Alarm wont be added to allowed watchdog alarms.")

    def _disallow_alarm_legacy(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, unit_path=None,
                               severity=None, fault_signature=None, bts_type='GNB'):

        if self._is_gnb() and bts_type == "GNB":
            self.gnb_alarms.disallow_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                           hw_path=hw_path, unit_path=unit_path, severity=severity,
                                           fault_signature=fault_signature)
        elif self._is_enb() and bts_type == "ENB":
            self.enb_alarms.disallow_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                           hw_path=hw_path, unit_path=unit_path, severity=severity,
                                           fault_signature=fault_signature)

    def _disallow_alarm_cni_127210(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, unit_path=None,
                                   severity=None, fault_signature=None, bts_type='GNB'):
        alarms_instance = None
        all_alarm_ids = self._get_all_alarms_and_severity_for_fault_id(fault_id=fault_id)
        hidden_alarm_ids = self._get_hidden_alarms_and_severity_for_fault_id(fault_id=fault_id)
        visible_alarm_ids = self._get_visible_alarms_and_severity_for_fault_id(all_alarm_ids=all_alarm_ids,
                                                                               hidden_alarm_ids=hidden_alarm_ids)

        if self._is_gnb() and bts_type == "GNB":
            alarms_instance = self.gnb_alarms

        elif self._is_enb() and bts_type == "ENB":
            alarms_instance = self.enb_alarms

        if alarms_instance:
            if alarm_id:
                self._disallow_alarm_with_alarm_id_and_severity(
                    alarm_instance=alarms_instance, alarm_id=alarm_id,
                    fault_id=fault_id, fault_name=fault_name,
                    hw_path=hw_path, unit_path=unit_path, severity=severity,
                    fault_signature=fault_signature, visible_alarm_ids=visible_alarm_ids,
                )
            elif visible_alarm_ids:
                self._disallow_alarm_without_alarm_id_provided(alarm_instance=alarms_instance,
                                                               fault_id=fault_id, fault_name=fault_name,
                                                               hw_path=hw_path, unit_path=unit_path,
                                                               fault_signature=fault_signature,
                                                               visible_alarm_ids=visible_alarm_ids)
            else:
                alarms_instance.disallow_alarm(fault_id=fault_id, fault_name=fault_name, hw_path=hw_path,
                                               unit_path=unit_path, fault_signature=fault_signature)

    @log_input_and_output
    def _disallow_alarm_with_alarm_id_and_severity(self, alarm_instance, alarm_id, fault_id, fault_name,
                                                   hw_path, unit_path, severity, fault_signature,
                                                   visible_alarm_ids):

        visible_alarm_severity_levels = self._verify_alarm_id_and_get_severity_levels(
            fault_id=fault_id,
            alarm_id=alarm_id,
            visible_alarm_ids=visible_alarm_ids
        )

        if severity:
            alarm_instance.disallow_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                          hw_path=hw_path, unit_path=unit_path, severity=severity,
                                          fault_signature=fault_signature)
        elif visible_alarm_severity_levels is not None:
            for disallowed_severity in visible_alarm_severity_levels:
                alarm_instance.disallow_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                              hw_path=hw_path, unit_path=unit_path, severity=disallowed_severity,
                                              fault_signature=fault_signature)

    @staticmethod
    @log_input_and_output
    def _disallow_alarm_without_alarm_id_provided(alarm_instance, fault_id, fault_name, hw_path, unit_path,
                                                  fault_signature, visible_alarm_ids):
        for visible_alarm_id in visible_alarm_ids:
            for disallowed_severity in visible_alarm_ids[visible_alarm_id]:
                alarm_instance.disallow_alarm(alarm_id=visible_alarm_id, fault_id=fault_id,
                                              fault_name=fault_name, hw_path=hw_path, unit_path=unit_path,
                                              severity=disallowed_severity, fault_signature=fault_signature)

    def _is_tmo_branch_with_unhidden_alarms(self):
        return self._sw_version.split('_')[-2] == "000425" and self._sw_version >= "SBTS24R3_ENB_0000_000425_000074"
